function _applyBeToggleStyle(btn, active) {
  if (!btn) return;
  if (active) {
    btn.innerHTML = '<span class="be-toggle-icon">🧭</span> Including shelf estimates';
    btn.classList.add('be-toggle-active');
  } else {
    btn.innerHTML = '<span class="be-toggle-icon">📓</span> Tracked sessions only';
    btn.classList.remove('be-toggle-active');
  }
}

function beToggleUntracked(btn) {
  const wasActive = btn.dataset.active === 'true';
  const nowActive = !wasActive;
  btn.dataset.active = nowActive ? 'true' : 'false';
  localStorage.setItem('be_include_untracked', nowActive);
  _applyBeToggleStyle(btn, nowActive);
  renderMoneySaved();
}


