function _loadCustomBrewers() {
  try { return JSON.parse(localStorage.getItem('bb_custom_brewers') || '[]'); } catch { return []; }
}
function _saveCustomBrewers(arr) {
  localStorage.setItem('bb_custom_brewers', JSON.stringify(arr));
}
function _loadCustomGrinders() {
  try { return JSON.parse(localStorage.getItem('bb_custom_grinders') || '[]'); } catch { return []; }
}
function _saveCustomGrinders(arr) {
  localStorage.setItem('bb_custom_grinders', JSON.stringify(arr));
}

function toggleCustomBrewerField() {
  const val = $('j-brewer').value;
  const wrap = $('j-brewer-custom-wrap');
  if (wrap) {
    wrap.style.display = val === 'other' ? 'block' : 'none';
    if (val !== 'other') {
      $('j-brewer-custom').value = '';
      $('j-brewer-save').checked = false;
    }
  }
}
function toggleCustomGrinderField() {
  const val = $('j-grinder').value;
  const wrap = $('j-grinder-custom-wrap');
  if (wrap) {
    wrap.style.display = val === 'other' ? 'block' : 'none';
    if (val !== 'other') {
      $('j-grinder-custom').value = '';
      $('j-grinder-save').checked = false;
    }
  }
}
function onGrinderChange() {
  toggleCustomGrinderField();
  const grinderVal = $('j-grinder').value;
  const grindInput = $('j-grind');
  if (grindInput) {
    if (grinderVal === '1Zpresso Q Air') {
      grindInput.placeholder = 'x.y.z (e.g. 3.4.1)';
    } else if (grinderVal === 'Kingrinder K6') {
      grindInput.placeholder = 'e.g. 60 clicks';
    } else {
      grindInput.placeholder = 'e.g. 3.5';
    }
  }
}

function populateBrewerGrinderDropdowns() {
  const defaultBrewers = ['Espresso Machine', 'Americano', 'V60', 'KaldiPress', 'AeroPress', 'French Press', 'Cold Brew', 'Cafflano Kompresso'];
  const customBrewers = _loadCustomBrewers();
  let brewerHTML = '<option value="">Select</option>';
  defaultBrewers.forEach(b => {
    brewerHTML += `<option value="${esc(b)}">${esc(b)}</option>`;
  });
  customBrewers.forEach(b => {
    brewerHTML += `<option value="${esc(b)}">${esc(b)}</option>`;
  });
  brewerHTML += '<option value="other">Other</option>';
  $('j-brewer').innerHTML = brewerHTML;

  const defaultGrinders = ['1Zpresso Q Air', 'Timemore C2/C3', 'Commandante C40', 'Fellow Ode', 'Niche Zero', 'Kingrinder K6', 'Pre-ground'];
  const customGrinders = _loadCustomGrinders();
  let grinderHTML = '<option value="">Select</option>';
  defaultGrinders.forEach(g => {
    grinderHTML += `<option value="${esc(g)}">${esc(g)}</option>`;
  });
  customGrinders.forEach(g => {
    grinderHTML += `<option value="${esc(g)}">${esc(g)}</option>`;
  });
  grinderHTML += '<option value="other">Other</option>';
  $('j-grinder').innerHTML = grinderHTML;
}


