/* ═══════════════════════════════════════════════════════════
   JOURNAL FILTER + PAGINATION
═══════════════════════════════════════════════════════════ */
let jPage = 0;
const J_PER_PAGE = 10;
let jFilteredEntries = null; // null = no filter active, shows all

let jFiltersInitialized = false;

function _initJournalFiltersFromUrl() {
  if (jFiltersInitialized) return;
  const params = new URLSearchParams(window.location.search);
  const search = params.get('search');
  const brewer = params.get('brewer');
  const grinder = params.get('grinder');
  const rating = params.get('rating');
  const bean = params.get('bean');
  const sort = params.get('sort');

  if (search && $('jFilterSearch')) $('jFilterSearch').value = search;
  if (brewer && $('jFilterBrewer')) $('jFilterBrewer').value = brewer;
  if (grinder && $('jFilterGrinder')) $('jFilterGrinder').value = grinder;
  if (rating && $('jFilterRating')) $('jFilterRating').value = rating;
  if (sort && $('jFilterSort')) $('jFilterSort').value = sort;

  if (bean && $('jFilterBean')) {
    const select = $('jFilterBean');
    const option = Array.from(select.options).find(opt => 
      opt.value === bean || opt.value === `id:${bean}` || opt.value === `label:${bean}`
    );
    if (option) select.value = option.value;
  }

  jFiltersInitialized = true;
  try {
    const cleanUrl = window.location.pathname;
    window.history.replaceState({}, document.title, cleanUrl);
  } catch (e) {
    console.error('Failed to clean url', e);
  }
}

function _getJournalFilterValues() {
  return {
    search: ($('jFilterSearch')?.value || '').toLowerCase().trim(),
    brewer: ($('jFilterBrewer')?.value || ''),
    grinder: ($('jFilterGrinder')?.value || ''),
    rating: parseInt($('jFilterRating')?.value || '0', 10),
    bean: ($('jFilterBean')?.value || ''),
    sort: ($('jFilterSort')?.value || 'date-desc'),
  };
}

function _populateJournalFilterDropdowns() {
  const brewerSel = $('jFilterBrewer');
  const grinderSel = $('jFilterGrinder');
  const beanSel = $('jFilterBean');
  if (!brewerSel || !beanSel) return;

  const brewers = [...new Set(journal.map(j => j.brewer).filter(Boolean))].sort();
  const currentBrewer = brewerSel.value;
  brewerSel.innerHTML = '<option value="">☕ All Brewers</option>' +
    brewers.map(b => `<option value="${b.replace(/"/g, '&quot;')}"${currentBrewer === b ? ' selected' : ''}>${esc(b)}</option>`).join('');

  if (grinderSel) {
    const grinders = [...new Set(journal.map(j => j.grinder).filter(Boolean))].sort();
    const currentGrinder = grinderSel.value;
    grinderSel.innerHTML = '<option value="">⚙️ All Grinders</option>' +
      grinders.map(g => `<option value="${g.replace(/"/g, '&quot;')}"${currentGrinder === g ? ' selected' : ''}>${esc(g)}</option>`).join('');
  }

  // Bean dropdown — use 'id:N' or 'label:name' as stable keys
  const beanMap = new Map(); // key -> display name
  journal.forEach(j => {
    if (j.beanId) {
      const name = logs.find(l => l.id === parseInt(j.beanId))?.name || j.beanLabel || '';
      const key = 'id:' + j.beanId;
      if (name && !beanMap.has(key)) beanMap.set(key, name);
    } else if (j.beanLabel) {
      const key = 'label:' + j.beanLabel;
      if (!beanMap.has(key)) beanMap.set(key, j.beanLabel);
    }
  });
  const currentBean = beanSel.value;
  const beanEntries = [...beanMap.entries()].sort((a, b) => a[1].localeCompare(b[1]));
  beanSel.innerHTML = '<option value="">🫘 All Beans</option>' +
    beanEntries.map(([key, name]) => `<option value="${key.replace(/"/g, '&quot;')}"${currentBean === key ? ' selected' : ''}>${esc(name)}</option>`).join('');
}

function _applyJournalSort(arr, sortKey) {
  const sorted = [...arr];
  switch (sortKey) {
    case 'date-asc':    sorted.sort((a, b) => new Date(a.date) - new Date(b.date) || Number(a.id) - Number(b.id)); break;
    case 'date-desc':   sorted.sort((a, b) => new Date(b.date) - new Date(a.date) || Number(b.id) - Number(a.id)); break;
    case 'rating-desc': sorted.sort((a, b) => (b.rating || 0) - (a.rating || 0) || new Date(b.date) - new Date(a.date) || Number(b.id) - Number(a.id)); break;
    case 'rating-asc':  sorted.sort((a, b) => (a.rating || 0) - (b.rating || 0) || new Date(b.date) - new Date(a.date) || Number(b.id) - Number(a.id)); break;
    default:            sorted.sort((a, b) => new Date(b.date) - new Date(a.date) || Number(b.id) - Number(a.id));
  }
  return sorted;
}

function applyJournalFilter() {
  jPage = 0;
  renderJournal();
}

function clearJournalFilter() {
  if ($('jFilterSearch'))  $('jFilterSearch').value  = '';
  if ($('jFilterBrewer'))  $('jFilterBrewer').value  = '';
  if ($('jFilterGrinder')) $('jFilterGrinder').value = '';
  if ($('jFilterRating'))  $('jFilterRating').value  = '';
  if ($('jFilterBean'))    $('jFilterBean').value    = '';
  if ($('jFilterSort'))    $('jFilterSort').value    = 'date-desc';
  jPage = 0;
  renderJournal();
}

// Wrap existing renderJournal to add filter + pagination
const _renderJournalOrig = renderJournal;
function renderJournal() {
  // Populate dropdowns fresh
  _populateJournalFilterDropdowns();

  // Initialize filters from URL parameters on first load
  _initJournalFiltersFromUrl();

  // Stats (always from full dataset)
  const total = journal.length;
  const rated = journal.filter(j => j.rating > 0);
  const avgR = rated.length ? (rated.reduce((s, j) => s + j.rating, 0) / rated.length).toFixed(1) : '—';
  const brCount = {};
  journal.forEach(j => { if (j.brewer) brCount[j.brewer] = (brCount[j.brewer] || 0) + 1; });
  const favBr = Object.entries(brCount).sort((a, b) => b[1] - a[1])[0]?.[0] || '—';
  if ($('jsTotal'))     $('jsTotal').textContent     = total;
  if ($('jsAvgRating')) $('jsAvgRating').textContent = avgR !== '—' ? avgR + '★' : '—';
  if ($('jsFavMethod')) $('jsFavMethod').textContent = favBr.split(' ')[0];
  // Savings
  const { totalSaved } = calcMoneySaved();
  if ($('jsSaved')) $('jsSaved').textContent = (totalSaved >= 0 ? '₹' : '-₹') +
    Math.abs(totalSaved).toLocaleString('en-IN', { maximumFractionDigits: 0 });

  // --- Apply filters ---
  const f = _getJournalFilterValues();
  const hasFilter = f.search || f.brewer || f.grinder || f.rating || f.bean;

  // Show/hide clear button
  if ($('jFilterClearBtn')) $('jFilterClearBtn').style.display = hasFilter ? 'flex' : 'none';

  let filtered = [...journal];

  if (f.brewer) {
    filtered = filtered.filter(j => (j.brewer || '') === f.brewer);
  }
  if (f.grinder) {
    filtered = filtered.filter(j => (j.grinder || '') === f.grinder);
  }
  if (f.rating) {
    filtered = filtered.filter(j => (j.rating || 0) >= f.rating);
  }
  if (f.bean) {
    filtered = filtered.filter(j => {
      if (f.bean.startsWith('id:')) {
        const keyId = f.bean.slice(3);
        return j.beanId && String(j.beanId) === keyId;
      } else if (f.bean.startsWith('label:')) {
        const keyLabel = f.bean.slice(6);
        return (j.beanLabel || '') === keyLabel;
      }
      return false;
    });
  }
  if (f.search) {
    filtered = filtered.filter(j => {
      const beanName = j.beanId ? (logs.find(l => l.id === parseInt(j.beanId))?.name || j.beanLabel || '') : (j.beanLabel || '');
      const haystack = [
        beanName, j.brewer || '', j.grinder || '', j.notes || '',
        ...(j.tastes || []),
      ].join(' ').toLowerCase();
      return haystack.includes(f.search);
    });
  }

  // Sort
  const sorted = _applyJournalSort(filtered, f.sort);

  // Filter summary
  const summaryEl = $('jFilterSummary');
  if (summaryEl) {
    if (hasFilter && sorted.length !== total) {
      summaryEl.style.display = 'block';
      summaryEl.textContent = `Showing ${sorted.length} of ${total} session${total !== 1 ? 's' : ''}`;
    } else if (hasFilter && sorted.length === 0) {
      summaryEl.style.display = 'block';
      summaryEl.textContent = 'No sessions match your filters';
    } else {
      summaryEl.style.display = 'none';
    }
  }

  const totalPages = Math.max(1, Math.ceil(sorted.length / J_PER_PAGE));
  jPage = Math.min(jPage, totalPages - 1);
  const slice = sorted.slice(jPage * J_PER_PAGE, (jPage + 1) * J_PER_PAGE);

  if (!slice.length) {
    if ($('journalList')) $('journalList').innerHTML = `<div class="empty-state"><div class="icon">📓</div><p>${hasFilter ? 'No sessions match your filters.' : 'No brew sessions yet. Log your first cup!'}</p>${hasFilter ? '<button class="btn-ghost" onclick="clearJournalFilter()" style="margin-top:.75rem">Clear filters</button>' : ''}</div>`;
    if ($('journalPagination')) $('journalPagination').innerHTML = '';
    return;
  }

  if ($('journalList')) {
    $('journalList').innerHTML = slice.map(j => {
      const stars = '★'.repeat(j.rating || 0) + '☆'.repeat(5 - (j.rating || 0));
      const tastes = (j.tastes || []).map(t => `<span class="taste-chip">${esc(t)}</span>`).join('');
      const metaBrewer = [];
      if (j.brewer) metaBrewer.push(`<span class="epill brew">☕ ${esc(j.brewer)}</span>`);
      if (j.is_milk_based) metaBrewer.push(`<span class="epill" style="color:var(--caramel);font-weight:600">🥛 Milk-based</span>`);

      const metaExtract = [];
      if (j.dose) metaExtract.push(`<span class="epill">${parseFloat(Number(j.dose).toFixed(1))}g dose</span>`);
      if (j.yield) metaExtract.push(`<span class="epill">${parseFloat(Number(j.yield).toFixed(1))}g yield</span>`);
      if (j.time) metaExtract.push(`<span class="epill">${j.time}s</span>`);
      if (j.temp) metaExtract.push(`<span class="epill">${j.temp}°C</span>`);

      const metaGrinder = [];
      if (j.grinder) metaGrinder.push(`<span class="epill">⚙️ ${esc(j.grinder)}</span>`);
      if (j.grind)   metaGrinder.push(`<span class="epill">📏 ${esc(j.grind)}</span>`);

      const beanName = j.beanId ? logs.find(l => l.id === parseInt(j.beanId))?.name || j.beanLabel || '' : j.beanLabel || '';
      return `<div class="journal-entry">
    <div class="je-header">
      <div>
        <div class="je-title">${beanName ? esc(beanName) : 'Brew Session'}</div>
        <div style="font-size:.72rem;color:var(--caramel);margin-top:.1rem">${stars}</div>
      </div>
      <div class="je-date">${fmtDate(j.date)}</div>
    </div>
    ${metaBrewer.length ? `<div class="je-meta" style="margin-top:.4rem">${metaBrewer.join('')}</div>` : ''}
    ${metaExtract.length ? `<div class="je-meta" style="margin-top:.2rem">${metaExtract.join('')}</div>` : ''}
    ${metaGrinder.length ? `<div class="je-meta" style="margin-top:.2rem">${metaGrinder.join('')}</div>` : ''}
    ${tastes ? `<div class="tasting-chips" style="margin-top:.4rem">${tastes}</div>` : ''}
    ${j.notes ? `<div class="je-notes">${esc(j.notes)}</div>` : ''}
    <div class="je-actions">
      <button class="action-btn share-btn" onclick="shareJournalEntry(${j.id})">↗ Share</button>
      <button class="action-btn" onclick="openJournalModal(${j.id})">Edit</button>
      <button class="action-btn del" onclick="deleteJournalEntry(${j.id})">✕</button>
    </div>
  </div>`;
    }).join('');
  }

  // Pagination controls
  const pagEl = $('journalPagination');
  if (pagEl) {
    if (totalPages > 1) {
      pagEl.innerHTML = `<div class="pag-bar">
        <button class="pag-btn" onclick="jPage=Math.max(0,jPage-1);renderJournal()" ${jPage === 0 ? 'disabled' : ''}>← Prev</button>
        <span class="pag-info">Page ${jPage + 1} of ${totalPages} · ${sorted.length} session${sorted.length !== 1 ? 's' : ''}</span>
        <button class="pag-btn" onclick="jPage=Math.min(${totalPages - 1},jPage+1);renderJournal()" ${jPage === totalPages - 1 ? 'disabled' : ''}>Next →</button>
      </div>`;
    } else {
      pagEl.innerHTML = `<div class="pag-info" style="text-align:center;padding:.5rem 0;font-size:.75rem;color:var(--mid)">${sorted.length} session${sorted.length !== 1 ? 's' : ''}</div>`;
    }
  }
}

/* ═══════════════════════════════════════════════════════════
   OWNER ACCESS & AUTH
═══════════════════════════════════════════════════════════ */
const CORRECT_PIN_HASH = 'f652f5c87c84f33899f9be3b2f62607ce5b61c68cac1f70bb4cdbb40d79b6904'; // PIN: 2811
const SESSION_KEY = 'brewlog_unlocked';
let isOwner = false;
let pinInput = '';

function applyAccessLevel() {
  if (isOwner) {
    document.body.classList.remove('visitor-mode');
  } else {
    document.body.classList.add('visitor-mode');
  }
  document.querySelectorAll('.owner-btn').forEach(btn => {
    btn.textContent = isOwner ? '🔓' : '🔐';
    btn.title = isOwner ? 'Owner mode – click to exit' : 'Owner Login';
  });
}

function toggleOwnerAccess() {
  if (isOwner) {
    isOwner = false;
    sessionStorage.removeItem(SESSION_KEY);
    applyAccessLevel();
  } else {
    showPinModal();
  }
}

function showPinModal() {
  pinInput = '';
  updateDots();
  document.getElementById('pin-overlay').classList.add('visible');
}
function hidePinModal() {
  document.getElementById('pin-overlay').classList.remove('visible');
}
function maybeHidePinModal(e) {
  if (e.target === document.getElementById('pin-overlay')) hidePinModal();
}

function updateDots(state) {
  for (let i = 0; i < 4; i++) {
    const d = document.getElementById('d' + i);
    if (!d) continue;
    d.className = 'pin-dot';
    if (state === 'ok') d.className = 'pin-dot filled ok';
    else if (state === 'error') d.className = 'pin-dot filled error';
    else if (i < pinInput.length) d.className = 'pin-dot filled';
  }
}

async function pinPress(digit) {
  if (pinInput.length >= 4) return;
  pinInput += digit;
  document.getElementById('pinErr').textContent = '';
  updateDots();
  if (pinInput.length === 4) await checkPin();
}
function pinDel() {
  pinInput = pinInput.slice(0, -1);
  document.getElementById('pinErr').textContent = '';
  updateDots();
}

async function sha256(msg) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(msg));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function checkPin() {
  const hash = await sha256(pinInput);
  if (hash === CORRECT_PIN_HASH) {
    updateDots('ok');
    isOwner = true;
    sessionStorage.setItem(SESSION_KEY, 'owner');
    setTimeout(() => {
      const overlay = document.getElementById('pin-overlay');
      overlay.classList.add('unlocking');
      setTimeout(() => overlay.classList.remove('visible', 'unlocking'), 400);
      applyAccessLevel();
      // If on add page, reload to show the form
      if (document.body.dataset.page === 'add') window.location.reload();
    }, 350);
  } else {
    updateDots('error');
    document.getElementById('pinErr').textContent = 'Incorrect PIN. Try again.';
    setTimeout(() => { pinInput = ''; updateDots(); }, 800);
  }
}

document.addEventListener('keydown', e => {
  if (!document.getElementById('pin-overlay').classList.contains('visible')) return;
  if (e.key >= '0' && e.key <= '9') pinPress(e.key);
  else if (e.key === 'Backspace') pinDel();
  else if (e.key === 'Escape') hidePinModal();
});

/* ═══════════════════════════════════════════════════════════
   MULTI-THEME ENGINE (Nordic Specialty, Luxury Bronze, Classic Barista)
═══════════════════════════════════════════════════════════ */
const THEMES = [
  {
    id: 'nordic',
    name: 'Nordic Specialty',
    desc: 'Clean porcelain & matcha sage',
    icon: '🌿',
    swatches: ['#F8FAFC', '#059669', '#0D9488', '#0F172A']
  },
  {
    id: 'luxury',
    name: 'Luxury Bronze',
    desc: 'Velvet chocolate & champagne gold',
    icon: '⚜️',
    swatches: ['#FBF7F0', '#C68B59', '#8C532B', '#1F140E']
  },
  {
    id: 'barista',
    name: 'Warm Barista',
    desc: 'Artisanal cream & caramel roast',
    icon: '☕',
    swatches: ['#F5EFE0', '#C47D2A', '#4A2C14', '#2C1A0E']
  }
];

function getCurrentTheme() {
  return localStorage.getItem('bb_theme') || 'nordic';
}

function getCurrentMode() {
  const saved = localStorage.getItem('theme');
  if (saved) return saved;
  return (typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light';
}

function setTheme(themeId) {
  localStorage.setItem('bb_theme', themeId);
  applyTheme();
  if (typeof document !== 'undefined' && document.body && document.body.dataset && document.body.dataset.page === 'insights' && typeof renderInsights === 'function') renderInsights();
}

function setMode(mode) {
  localStorage.setItem('theme', mode);
  applyTheme();
  if (typeof document !== 'undefined' && document.body && document.body.dataset && document.body.dataset.page === 'insights' && typeof renderInsights === 'function') renderInsights();
}

function toggleTheme() {
  openThemeModal();
}

function applyTheme() {
  const theme = getCurrentTheme();
  const mode = getCurrentMode();

  if (typeof document !== 'undefined' && document.documentElement) {
    document.documentElement.setAttribute('data-theme', theme);
  }
  if (typeof document !== 'undefined' && document.body) {
    document.body.setAttribute('data-theme', theme);
    if (mode === 'dark') {
      document.body.classList.add('dark-mode');
    } else {
      document.body.classList.remove('dark-mode');
    }
  }
  updateThemeUI();
}

try {
  applyTheme();
} catch (e) {}

function updateThemeUI() {
  if (typeof document === 'undefined') return;
  const mode = getCurrentMode();
  const theme = getCurrentTheme();
  const activeThemeObj = THEMES.find(t => t.id === theme) || THEMES[0];

  if (typeof document.querySelectorAll === 'function') {
    document.querySelectorAll('.theme-toggle').forEach(btn => {
      btn.innerHTML = `${activeThemeObj.icon}`;
      if (typeof btn.setAttribute === 'function') btn.setAttribute('title', `Theme: ${activeThemeObj.name} (${mode})`);
    });

    document.querySelectorAll('.theme-card-option').forEach(el => {
      if (el.dataset && el.dataset.themeId === theme) {
        el.classList.add('selected');
      } else {
        el.classList.remove('selected');
      }
    });
  }

  const lightBtn = typeof document.getElementById === 'function' ? document.getElementById('theme-mode-light') : null;
  const darkBtn = typeof document.getElementById === 'function' ? document.getElementById('theme-mode-dark') : null;
  if (lightBtn && darkBtn) {
    if (mode === 'dark') {
      darkBtn.classList.add('active');
      lightBtn.classList.remove('active');
    } else {
      lightBtn.classList.add('active');
      darkBtn.classList.remove('active');
    }
  }
}

function openThemeModal() {
  if (typeof document === 'undefined' || !document.body) return;
  let modalOverlay = document.getElementById('themeModalOverlay');
  if (!modalOverlay) {
    modalOverlay = document.createElement('div');
    modalOverlay.id = 'themeModalOverlay';
    modalOverlay.className = 'theme-modal-overlay';
    
    const themeGridHtml = THEMES.map(t => `
      <div class="theme-card-option ${t.id === getCurrentTheme() ? 'selected' : ''}" data-theme-id="${t.id}" onclick="setTheme('${t.id}')">
        <div class="theme-card-info">
          <span class="theme-card-icon">${t.icon}</span>
          <div>
            <div class="theme-card-name">${t.name}</div>
            <div class="theme-card-desc">${t.desc}</div>
          </div>
        </div>
        <div class="theme-swatches">
          ${t.swatches.map(c => `<span class="theme-swatch" style="background:${c}"></span>`).join('')}
        </div>
      </div>
    `).join('');

    modalOverlay.innerHTML = `
      <div class="theme-modal-card">
        <div class="theme-modal-header">
          <div class="theme-modal-title">🎨 Theme & Palette</div>
          <button class="theme-modal-close" onclick="closeThemeModal()">&times;</button>
        </div>
        <div class="theme-picker-grid">
          ${themeGridHtml}
        </div>
        <div class="theme-mode-row">
          <span class="theme-mode-label">Appearance</span>
          <div class="theme-mode-toggle-wrap">
            <button id="theme-mode-light" class="theme-mode-btn ${getCurrentMode() === 'light' ? 'active' : ''}" onclick="setMode('light')">☀️ Light</button>
            <button id="theme-mode-dark" class="theme-mode-btn ${getCurrentMode() === 'dark' ? 'active' : ''}" onclick="setMode('dark')">🌙 Dark</button>
          </div>
        </div>
      </div>
    `;

    modalOverlay.addEventListener('click', (e) => {
      if (e.target === modalOverlay) closeThemeModal();
    });

    document.body.appendChild(modalOverlay);
  }

  updateThemeUI();
  modalOverlay.classList.add('active');
}

function closeThemeModal() {
  if (typeof document === 'undefined') return;
  const modalOverlay = document.getElementById('themeModalOverlay');
  if (modalOverlay) modalOverlay.classList.remove('active');
}

/* ═══════════════════════════════════════════════════════════
   PAGE-AWARE BOOT
═══════════════════════════════════════════════════════════ */
document.addEventListener('DOMContentLoaded', async () => {
  // Restore session
  if (sessionStorage.getItem(SESSION_KEY) === 'owner') isOwner = true;

  applyTheme();
  applyAccessLevel();

  const page = document.body.dataset.page || 'insights';

  // Add-page: guard non-owners before even loading data
  if (page === 'add' && !isOwner) {
    const main = document.getElementById('add-main');
    if (main) main.innerHTML = `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:55vh;text-align:center;padding:2rem">
      <div style="font-size:3rem;margin-bottom:1rem">🔐</div>
      <div style="font-family:'Playfair Display',serif;font-size:1.4rem;color:var(--roast);margin-bottom:.5rem">Owner access required</div>
      <div style="font-size:.8rem;color:var(--mid);margin-bottom:1.5rem">Log in to add or edit orders.</div>
      <button class="btn-primary" onclick="showPinModal()">🔐 Log In</button>
    </div>`;
    return; // skip data load
  }

  // Add-page pre-setup
  if (page === 'add') {
    if ($('inp-date')) $('inp-date').valueAsDate = new Date();
    if ($('itemsList')) addItemRow();
  }

  await loadData();

  switch (page) {
    case 'insights': renderInsights(); break;
    case 'log': renderAll(); break;
    case 'shelf': renderShelf(); break;
    case 'process': renderProcess(); break;
    case 'journal': renderJournal(); break;
    case 'add': {
      const editId = new URLSearchParams(window.location.search).get('edit');
      if (editId) {
        // pre-fill form for editing
        const entry = logs.find(l => l.id === parseInt(editId));
        if (entry) {
          editingId = parseInt(editId);
          if ($('addPageTitle')) $('addPageTitle').innerHTML = 'Edit <em>Entry</em>';
          if ($('editBanner')) { $('editBanner').textContent = `Editing "${entry.name}". Update and save.`; $('editBanner').classList.add('active'); }
          if ($('inp-date')) $('inp-date').value = entry.date;
          if ($('inp-order')) $('inp-order').value = entry.order_id || '';
          if ($('inp-vendor')) $('inp-vendor').value = entry.vendor;
          const isCombo = entry.is_combo === 1;
          if ($('inp-combo')) { $('inp-combo').checked = isCombo; }
          if ($('inp-combo-price')) $('inp-combo-price').value = entry.combo_price || '';
          if ($('comboPriceWrap')) $('comboPriceWrap').classList.toggle('active', isCombo);
          if ($('itemsList')) { $('itemsList').innerHTML = ''; itemCount = 0; addItemRow(entry); }
        }
      }
      break;
    }
  }
});

// Prevent number inputs from changing values when scrolling
document.addEventListener('wheel', function (e) {
  if (document.activeElement && document.activeElement.type === 'number') {
    document.activeElement.blur();
  }
});
